SourceCode.Declaration:
/// <summary>
/// CB731_LaserNetBundleTOMultithreadBatch.
/// Data contract class for the order shipment bundling reporting job.
/// </summary>
[DataContract]
class METOrderShipmentBundlingReportingJobContract extends METSysOperationTaskDataContract
{
    guid topPickingProcessId;
    str printDestSettingsPacked;
    str packedQuery;
    METOrderTransactionType transcationType;

}

Method.Source:
/// <summary>
/// Gets/sets transcation type.
/// </summary>
/// <param name = "transcationType">Transcation type</param>
/// <returns>Transcation type</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public METOrderTransactionType parmTranscationType(METOrderTransactionType _transcationType = transcationType)
{
    transcationType = _transcationType;
    return transcationType;
}

/// <summary>
/// Gets/sets packed print destination settings.
/// </summary>
/// <param name = "_printDestSettingsPacked">Packed print destination settings.</param>
/// <returns>Packed print destination settings.</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public str parmPrintDestSettingsPacked(str _printDestSettingsPacked = printDestSettingsPacked)
{
    printDestSettingsPacked = _printDestSettingsPacked;
    return printDestSettingsPacked;
}

/// <summary>
/// Provides thread count parameter
/// </summary>
/// <param name = "_threadCount">Number of sub tasks spawned from main tasks</param>
/// <returns>The thread count</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
{
    threadCount = _threadCount;

    return threadCount;
}

/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;

    return topPickingProcessId;
}

/// <summary>
/// Gets/sets packed query.
/// </summary>
/// <param name = "_packedQuery">Packed query.</param>
/// <returns>Packed query.</returns>
[DataMemberAttribute,
 AifQueryTypeAttribute('_packedQuery', queryStr(METOrderShipmentBundlingReportingJobQuery))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Gets query.
/// </summary>
/// <returns>
/// Query.
/// </returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Sets query.
/// </summary>
/// <param name = "_query">
/// Query.
/// </param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}

/// <summary>
/// Saves <c>SRSPrintDestinationSettings></c> in base64 form.
/// </summary>
/// <param name = "_printDestinationSettings"><c>SRSPrintDestinationSettings</c>.</param>
public void setPrintDestinationSettings(SRSPrintDestinationSettings _printDestinationSettings)
{
    printDestSettingsPacked = SysOperationHelper::base64Encode(_printDestinationSettings.pack());
}

/// <summary>
/// Retrieves <c>SRSPrintDestinationSettings></c> from a base64 form.
/// </summary>
/// <returns><c>SRSPrintDestinationSettings></c>.</returns>
public SRSPrintDestinationSettings getPrintDestinationSettings()
{
    SRSPrintDestinationSettings printDestinationSettings;

    printDestinationSettings = new SRSPrintDestinationSettings(SysOperationHelper::base64Decode(printDestSettingsPacked));

    return printDestinationSettings;
}
